import 'dart:async';
import 'package:light/light.dart';

StreamSubscription<int>? _sub;

Future<void> start() async {
  await Light().requestAuthorization(); // no‑op on Android
  _sub = Light().lightSensorStream.listen((int lux) {
    print('Lux: $lux');
  });
}

void stop() => _sub?.cancel();
